import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type SpendStatus = 'active' | 'risk' | 'paused' | 'archived';

type SpendProject = {
  id: string;
  name: string;
  quotaUsed: number;
  status: SpendStatus;
};

const PAGE_SIZE = 5;

const STATUS_META: Record<SpendStatus, { label: string; tone: 'success' | 'danger' | 'warning' | 'default' }> = {
  active: { label: 'Активен', tone: 'success' },
  risk: { label: 'Превышение', tone: 'danger' },
  paused: { label: 'На паузе', tone: 'warning' },
  archived: { label: 'В архиве', tone: 'default' },
};

const ALL_STATUSES: SpendStatus[] = ['active', 'risk', 'paused', 'archived'];

const PROJECTS: SpendProject[] = [
  { id: 'p1', name: 'Контекст-лаборатория', quotaUsed: 72, status: 'active' },
  { id: 'p2', name: 'Поисковый индекс', quotaUsed: 96, status: 'risk' },
  { id: 'p3', name: 'Витрина отчётов', quotaUsed: 34, status: 'active' },
  { id: 'p4', name: 'Миграция биллинга', quotaUsed: 58, status: 'paused' },
  { id: 'p5', name: 'Мобильный клиент', quotaUsed: 81, status: 'active' },
  { id: 'p6', name: 'Импорт логов', quotaUsed: 100, status: 'risk' },
  { id: 'p7', name: 'Справочник тарифов', quotaUsed: 12, status: 'archived' },
  { id: 'p8', name: 'Очередь уведомлений', quotaUsed: 65, status: 'active' },
  { id: 'p9', name: 'Экспорт в хранилище', quotaUsed: 47, status: 'paused' },
  { id: 'p10', name: 'Панель администратора', quotaUsed: 23, status: 'archived' },
  { id: 'p11', name: 'Шлюз вебхуков', quotaUsed: 88, status: 'risk' },
  { id: 'p12', name: 'Аналитика запросов', quotaUsed: 55, status: 'active' },
];

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<SpendStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeStatus = (status: SpendStatus) => {
    setStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(ALL_STATUSES);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: '20px' }}>
          Расход по проектам
        </h2>
        <p style={{ margin: '4px 0 0', color: 'var(--jx-text-2)', fontSize: '14px' }}>
          Заполненность квоты за текущий период
        </p>
      </div>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {statuses.map((status) => (
          <JxChip key={status} active removable onRemove={() => removeStatus(status)}>
            {STATUS_META[status].label}
          </JxChip>
        ))}
        {statuses.length < ALL_STATUSES.length && (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        )}
      </div>

      <JxDivider />

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не подходит ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 14px',
                  background: 'var(--jx-surface-2)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle value={project.quotaUsed} showValue />
                <span style={{ flex: 1, minWidth: 0, fontSize: '15px' }}>{project.name}</span>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

